const fs=require('fs');
const board=JSON.parse(fs.readFileSync('board.json','utf8'));
function play(rolls){
  const ps=['Peter','Billy','Charlotte','Sweedal'].map(n=>({n,m:16,p:0,b:false}));
  const own=new Map(); let played=0;
  for(let t=0;t<rolls.length;t++){
    const pl=ps[t%4]; const raw=pl.p+rolls[t];
    pl.m+=Math.floor(raw/board.length); pl.p=raw%board.length; played++;
    const s=board[pl.p];
    if(s.type==='property'){
      const o=own.get(pl.p);
      if(o===undefined){ if(pl.m>=s.price){pl.m-=s.price;own.set(pl.p,pl);} else {pl.m=0;pl.b=true;} }
      else if(o!==pl){
        const full=board.every((x,i)=>x.colour!==s.colour||own.get(i)===o);
        const rent=s.price*(full?2:1); const paid=Math.min(pl.m,rent);
        pl.m-=paid;o.m+=paid; if(paid<rent)pl.b=true;
      }
    }
    if(pl.b)break;
  }
  return {played,total:rolls.length,players:ps.map(p=>`${p.n} $${p.m} on ${board[p.p].name}${p.b?' (bankrupt)':''}`)};
}
